using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Threading.Tasks;using System.Windows.Forms;using V15Voice;
public static class UiFeatureTests {
 static int count;static object F(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}
 static IEnumerable<Control> Walk(Control c){foreach(Control k in c.Controls){yield return k;foreach(var q in Walk(k))yield return q;}}
 static void Check(bool yes,string s){if(!yes)throw new Exception(s);Console.WriteLine("PASS "+s);count++;}
 static void Screen(Form f,string name){Application.DoEvents();using(var bitmap=new System.Drawing.Bitmap(f.Width,f.Height))using(var g=System.Drawing.Graphics.FromImage(bitmap)){g.CopyFromScreen(f.Location,System.Drawing.Point.Empty,f.Size);bitmap.Save("/tmp/"+name+".png");}}
 [STAThread]public static void Main(){Application.EnableVisualStyles();var f=new MainForm();int code=0;f.Shown+=async(s,e)=>{try{
  var tabs=(TabControl)F(f,"tabs");Check(tabs.TabPages.Count==6,"Six tabs expose Studio, queue, library, tools, cloning and guide");tabs.SelectedIndex=3;Screen(f,"v15_140_tools");Check(Walk(tabs.TabPages[3]).OfType<Button>().Any(b=>b.Text=="So sánh 3–5 giọng"),"Comparison tool is visible in its own tools tab");
  tabs.SelectedIndex=4;var page=tabs.TabPages[4];var path=Walk(page).OfType<TextBox>().First(t=>t.ReadOnly);var name=Walk(page).OfType<TextBox>().First(t=>t.Width==300&&!t.ReadOnly);var rights=Walk(page).OfType<CheckBox>().Single();string dir=Path.Combine(Path.GetTempPath(),"v15_ui_feature_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string sample=Path.Combine(dir,"reference.wav");var w=Wave.Read(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"samples","03_Heart_US.wav"));new Wave{Rate=w.Rate,Samples=w.Samples.Concat(w.Samples).Concat(w.Samples).ToArray()}.Write(sample);path.Text=sample;name.Text="Giọng riêng thử nghiệm";rights.Checked=true;
  var save=Walk(page).OfType<Button>().First(b=>b.Text=="LƯU GIỌNG RIÊNG");((ScrollableControl)save.Parent).ScrollControlIntoView(save);save.PerformClick();for(int i=0;i<150&&(bool)F(f,"busy");i++)await Task.Delay(100);Check(!(bool)F(f,"busy"),"Reference import completes asynchronously and releases controls");var cat=(VoiceCatalog)F(f,"catalog");var own=cat.All.Single(p=>p.Key.StartsWith("U:"));Check(File.Exists(own.ReferencePath)&&own.ModelFolder=="qwen_base","Cloning tab stores local reference and registers Qwen Base voice");Check(((VoiceItem)((ComboBox)F(f,"voices")).SelectedItem).Key==own.Key,"New custom voice is immediately selected in Studio");Screen(f,"v15_140_clone");
  string script=Path.Combine(dir,"persist.txt");File.WriteAllText(script,"This queue entry survives an application restart.");Call(f,"AddFiles",new object[]{new[]{script}});Call(f,"SaveSession");using(var restored=new MainForm()){Check(((List<BatchJob>)F(restored,"jobs")).Count==1,"Opening another app instance restores queue without overwriting it empty");Check(((VoiceItem)((ComboBox)F(restored,"voices")).SelectedItem).Key==own.Key,"Last selected custom voice survives restart");Check(((VoiceCatalog)F(restored,"catalog")).All.Any(p=>p.Key==own.Key),"Custom voice catalog survives restart");}
  bool seen=false,finished=false;Exception comparisonError=null;var timer=new Timer{Interval=200};int ticks=0;timer.Tick+=(a,b)=>{try{var dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x.Text.StartsWith("So sánh 3–5"));if(dialog==null)return;if(!seen){seen=true;var list=Walk(dialog).OfType<CheckedListBox>().Single();var gender=Walk(dialog).OfType<ComboBox>().First(v=>v.Items.Count==3);gender.SelectedIndex=1;Check(list.Items.Cast<VoiceProfile>().Any(p=>p.Kind==EngineKind.LibriTTS),"Gender filter includes Libri profiles carrying source gender labels");gender.SelectedIndex=0;for(int i=0;i<3;i++)list.SetItemChecked(i,true);var text=Walk(dialog).OfType<TextBox>().First(t=>t.Multiline);text.Text="A quiet room can hide a strange story.";Walk(dialog).OfType<Button>().First(v=>v.Text=="TẠO MẪU SO SÁNH").PerformClick();}
   if(seen&&!(bool)F(f,"busy")){int results=Walk(dialog).OfType<Button>().Count(v=>v.Text.StartsWith("▶ "));Check(results==3,"Comparison generates three real offline samples from one text");Screen(dialog,"v15_140_compare");finished=true;timer.Stop();dialog.Close();}else if(++ticks>250)throw new Exception("Comparison timed out");
  }catch(Exception comparisonException){comparisonError=comparisonException;timer.Stop();foreach(var dialog in Application.OpenForms.Cast<Form>().Where(openForm=>openForm!=f).ToList())dialog.Close();}};timer.Start();Call(f,"CompareVoices");timer.Dispose();if(comparisonError!=null)throw comparisonError;Check(seen&&finished,"Comparison dialog finishes and cleans up without hanging");
  tabs.SelectedIndex=1;Screen(f,"v15_140_queue");Check(((Label)F(f,"batchInfo")).Text.Contains("hơi thở"),"Queue displays shared voice, speed and breath mode");
  Console.WriteLine("TOTAL "+count+" passed");
 }catch(Exception x){Console.WriteLine("FAIL "+x);code=1;}finally{f.Close();}};Application.Run(f);Environment.Exit(code);}
}
